//! Generated-file headers: a cheap check of a file's first bytes for the usual
//! markers.
//!
//! | Marker | Convention |
//! |---|---|
//! | `Code generated … DO NOT EDIT.` | Go (`go generate`, protoc-gen-go, sqlc, mockgen, …): one line matching `^// Code generated .* DO NOT EDIT\.$` |
//! | `@generated` | Facebook/Relay/Thrift/Cargo convention (not `@generated/…` package names) |
//! | `This file was automatically generated` | openapi-generator, json-schema-to-typescript, many others (case-insensitive) |
//! | `Generated by the protocol buffer compiler.  DO NOT EDIT!` | protoc's Python, C++ and Java output |
//!
//! The graph store calls [`generated_marker`] on each freshly read first-party
//! file: a file with a marker gets a `generated_file` uncertainty naming it,
//! which generated-file linking removes when a task output covers the file. So
//! a source importing a generated file whose producer is unknown reaches an
//! uncertainty instead of silently missing the generator's inputs.

/// How many leading bytes are checked.
pub const HEAD_BYTES: usize = 1024;

/// The marker in the first [`HEAD_BYTES`] of `src`, if any.
pub fn generated_marker(src: &[u8]) -> Option<&'static str> {
    let head = &src[..src.len().min(HEAD_BYTES)];
    // Cheap reject: every marker contains `generated` (any case).
    if memchr::memmem::find(head, b"enerated").is_none()
        && memchr::memmem::find(head, b"ENERATED").is_none()
    {
        return None;
    }
    for line in head.split(|&b| b == b'\n') {
        let line = trim(line);
        if go_marker(line) {
            return Some("Code generated … DO NOT EDIT.");
        }
    }
    let mut from = 0;
    while let Some(i) = memchr::memmem::find(&head[from..], b"@generated") {
        let at = from + i;
        let after = head.get(at + "@generated".len()).copied();
        let before = at.checked_sub(1).and_then(|j| head.get(j)).copied();
        let word_end = !after.is_some_and(|c| {
            c.is_ascii_alphanumeric() || matches!(c, b'/' | b'-' | b'_' | b'.' | b'\'' | b'"')
        });
        let word_start =
            !before.is_some_and(|c| c.is_ascii_alphanumeric() || matches!(c, b'\'' | b'"' | b'/'));
        if word_end && word_start {
            return Some("@generated");
        }
        from = at + 1;
    }
    let lower = head.to_ascii_lowercase();
    if memchr::memmem::find(&lower, b"this file was automatically generated").is_some() {
        return Some("This file was automatically generated");
    }
    if memchr::memmem::find(head, b"Generated by the protocol buffer compiler.").is_some() {
        return Some("Generated by the protocol buffer compiler");
    }
    None
}

/// `// Code generated <anything> DO NOT EDIT.` (Go's rule, also with `#`
/// comments).
fn go_marker(line: &[u8]) -> bool {
    let body = line
        .strip_prefix(b"//")
        .or_else(|| line.strip_prefix(b"#"))
        .or_else(|| line.strip_prefix(b"--"))
        .or_else(|| line.strip_prefix(b"/*"))
        .map(trim);
    let Some(body) = body else {
        return false;
    };
    let body = body.strip_suffix(b"*/").map(trim).unwrap_or(body);
    body.starts_with(b"Code generated ") && body.ends_with(b"DO NOT EDIT.")
}

fn trim(s: &[u8]) -> &[u8] {
    let s = match s.iter().position(|b| !b.is_ascii_whitespace()) {
        Some(i) => &s[i..],
        None => return &[],
    };
    let end = s
        .iter()
        .rposition(|b| !b.is_ascii_whitespace())
        .map_or(0, |i| i + 1);
    &s[..end]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn markers() {
        assert_eq!(
            generated_marker(
                b"// Code generated by \"stringer -type=Color\"; DO NOT EDIT.\n\npackage x\n"
            ),
            Some("Code generated … DO NOT EDIT.")
        );
        assert_eq!(
            generated_marker(b"# Code generated by sqlc. DO NOT EDIT.\r\n"),
            Some("Code generated … DO NOT EDIT.")
        );
        assert_eq!(
            generated_marker(b"/**\n * @generated SignedSource<<x>>\n */"),
            Some("@generated")
        );
        assert_eq!(
            generated_marker(b"/* tslint:disable */\n/**\n * This file was automatically generated by json-schema-to-typescript.\n */"),
            Some("This file was automatically generated")
        );
        assert_eq!(
            generated_marker(b"# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n"),
            Some("Generated by the protocol buffer compiler")
        );
        assert_eq!(generated_marker(b"require('@generated/photon');\n"), None);
        assert_eq!(
            generated_marker(b"// Code generated by hand, feel free to edit\n"),
            None
        );
        assert_eq!(generated_marker(b"const x = 'generated';\n"), None);
        assert_eq!(generated_marker(b"x = \"@generated\"\n"), None);
    }
}
